WITH lieu AS (SELECT geom FROM dvf.lieux WHERE nom = 'Place de la Bourse'),
ventes_apartments AS (SELECT ST_Distance(ventes.geom, lieu.geom) / 1000 AS dist_km, ventes.prix_m2 FROM dvf.ventes CROSS JOIN lieu WHERE ventes.annee = 2024 AND ventes.type_bien = 'Appartement' AND ventes.vente_reference = true AND ventes.prix_m2 IS NOT NULL)
SELECT CASE WHEN dist_km < 1 THEN '0-1 km' WHEN dist_km < 2 THEN '1-2 km' WHEN dist_km < 3 THEN '2-3 km' WHEN dist_km < 4 THEN '3-4 km' WHEN dist_km < 5 THEN '4-5 km' END AS tranche_distance, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY prix_m2) AS prix_m2_median, COUNT(*) AS nb_ventes FROM ventes_apartments WHERE dist_km < 5 GROUP BY tranche_distance ORDER BY MIN(dist_km);

